import zipfile, json, re

# Load event data
with open('event_data.json', 'r', encoding='utf-8') as f:
    event_data = json.load(f)

def flatten_json(obj, prefix=''):
    items = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_key = f'{prefix}{k}' if not prefix else f'{prefix}.{k}'
            if isinstance(v, (dict, list)):
                items.update(flatten_json(v, new_key))
            else:
                items[new_key] = str(v)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            items.update(flatten_json(v, f'{prefix}[{i}]'))
    return items

replacements = {}
if isinstance(event_data, dict):
    for k, v in event_data.items():
        if not isinstance(v, (dict, list)):
            replacements[k] = str(v)
    replacements.update(flatten_json(event_data))

print('Replacement keys:', list(replacements.keys()))

input_path = 'event_announcement_template.hwpx'
output_path = '/root/event_announcement_ready.hwpx'

TAG_PATTERNS = [
    r'<[a-zA-Z0-9_\-]*:?linesegarray[^>]*>.*?</[a-zA-Z0-9_\-]*:?linesegarray>',
    r'<[a-zA-Z0-9_\-]*:?lineSegArray[^>]*>.*?</[a-zA-Z0-9_\-]*:?lineSegArray>',
    r'<[a-zA-Z0-9_\-]*:?LineSegArray[^>]*>.*?</[a-zA-Z0-9_\-]*:?LineSegArray>',
    r'<[a-zA-Z0-9_\-]*:?LineSeg[^>]*>.*?</[a-zA-Z0-9_\-]*:?LineSeg>',
    r'<[a-zA-Z0-9_\-]*:?lineseg[^>]*>.*?</[a-zA-Z0-9_\-]*:?lineseg>',
]

with zipfile.ZipFile(input_path, 'r') as zin:
    with zipfile.ZipFile(output_path, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            out_data = data

            try:
                text = data.decode('utf-8')
            except UnicodeDecodeError:
                zout.writestr(item, out_data)
                continue

            if '{{' in text:
                original_text = text
                print(f'Processing: {item.filename}')

                # Replace exact placeholders
                for key, value in replacements.items():
                    text = text.replace('{{' + key + '}}', value)

                modified = (text != original_text)
                if modified:
                    # Remove layout cache elements (linesegarray and similar)
                    for tag_pattern in TAG_PATTERNS:
                        text = re.sub(tag_pattern, '', text, flags=re.DOTALL | re.IGNORECASE)

                remaining = re.findall(r'\{\{[^}]+\}\}', text)
                if remaining:
                    # De-duplicate while preserving order
                    seen = set()
                    uniq = []
                    for r in remaining:
                        if r not in seen:
                            seen.add(r)
                            uniq.append(r)
                    print(f'  WARNING: Remaining placeholders: {uniq}')

                out_data = text.encode('utf-8')

            zout.writestr(item, out_data)

print('Output written to', output_path)
